				, LAST_LOGIN_TIME
				, LAST_LOGIN_IP
				, THEME
				, DATE_FORMAT
				, CTRL_CODE
				, RESPONSIBILITY
				)
			VALUES 
			(
				 ${session.HOUSE_CODE}
				, ${USER_ID}
				, ${PASSWORD_1}
				, 'N'
				, ${current.DATE}  
				, ${current.DATE}
				, ${current.TIME}
				, ${USER_ID}
				, ${current.DATE}
				, ${current.TIME}
				, ${USER_ID}
				, ${COMPANY_CODE}
				, ${PLANT_CODE}
				, ${USER_NAME_LOC}
				, ${USER_NAME_ENG}
				, ${DEPT}
				, ${POSITION}
				, ${LANGUAGE}
				, ${MENU_TYPE}
				, ${TIME_ZONE}
				, ${EMAIL}
				, ${COUNTRY}
				, ${STATE}
				, ${EMPLOYEE_NO}
				, 'A'
				, ${WORK_TYPE}
				, ${MENU_PROFILE_CODE}
				, ${USER_TYPE}
				, '0'
				, 'N'
				, ${current.DATE}
				, ${current.TIME}
				, ${LAST_LOGIN_IP}
				, ${THEME}
				, '%Y/%m/%d'
				, ${CTRL_CODE}
				, ${RESPONSIBILITY}
			)


    	UPDATE SUSMT SET
				COMPANY_CODE   = #DB_OWNER#NVL(${COMPANY_CODE},COMPANY_CODE)
				, PLANT_CODE     = ${PLANT_CODE}
				, CHANGE_DATE    = ${current.DATE}
				, CHANGE_TIME    = ${current.TIME}
				, DEPT           = ${DEPT}
				, USER_NAME_LOC  = ${USER_NAME_LOC}
				, USER_NAME_ENG  = ${USER_NAME_ENG}
				, LANGUAGE       = ${LANGUAGE}
				, TIME_ZONE      = ${TIME_ZONE}
				, EMAIL          = ${EMAIL}
				, COUNTRY        = ${COUNTRY}
				, STATE          = ${STATE}
				, EMPLOYEE_NO    = #DB_OWNER#NVL(${EMPLOYEE_NO},EMPLOYEE_NO)
				, SIGN_STATUS    = 'A'
				, POSITION       = ${POSITION}
				, WORK_TYPE      = ${WORK_TYPE}
				, USER_TYPE      = ${USER_TYPE}
				, THEME          = ${THEME}
				, CHANGE_USER_ID = ${session.ID}
				, DATE_FORMAT    = '%Y/%m/%d'
				, RESPONSIBILITY = ${RESPONSIBILITY}
				, MENU_PROFILE_CODE = ${MENU_PROFILE_CODE}
		WHERE USER_ID = ${USER_ID}
		AND HOUSE_CODE = ${session.HOUSE_CODE}


 SELECT DEPT
	, DEPT_NAME_LOC
	FROM S0015
	WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
	AND COMPANY_CODE = ${session.COMPANY_CODE}
